'use strict';

// MODULES //

var objectKeys = require( '@stdlib/utils/keys' );
var groupValuesOnKey = require( '@stdlib/array/base/group-values-on-key' );
var DataSet = require( '@stdlib/plot/vega/data/values' );


// MAIN //

/**
* Splits a tidy data set into multiple data sets according to a specified key.
*
* @param {DataSet} data - input data set
* @param {string} key - property name which is used to group data elements
* @returns {Array<DataSet>} array of data sets
*
* @example
* var objarray2tidy = require( '@stdlib/plot/vega/data/tidy/from-object-array' );
*
* var x = [
*     {
*         'x': 0,
*         'y': 1
*     },
*     {
*         'x': 1,
*         'y': 2
*     },
*     {
*         'x': 0,
*         'y': 3
*     }
* ];
*
* var v = splitOnKey( objarray2tidy( x, 'series' ), 'x' );
* // returns [ <DataSet>, <DataSet> ]
*/
function splitOnKey( data, key ) {
	var groups;
	var keys;
	var out;
	var d;
	var i;

	// TODO: add input argument validation

	groups = groupValuesOnKey( data.values, key );
	keys = objectKeys( groups );

	out = [];
	for ( i = 0; i < keys.length; i++ ) {
		d = new DataSet({
			'name': keys[ i ],
			'values': groups[ keys[ i ] ]
		});
		out.push( d );
	}
	return out;
}


// EXPORTS //

module.exports = splitOnKey;
